        if (osName.contains("windows") && osVersion.startsWith("5.0")) {
            parent = new File("C:\\Documents and Settings");
        } else {
            String userHome = System.getProperty("user.home");
            if (userHome == null || userHome.isEmpty()) {
                throw new IllegalStateException("user.home system property is not set");
            }
            parent = new File(userHome);
        }
        if (!parent.exists() && !parent.mkdirs()) {
            throw new IllegalStateException("Could not create parent directory: " + parent.getAbsolutePath());
        }
        File configDir = new File(parent, "lf5");
        if (!configDir.exists() && !configDir.mkdirs()) {
            throw new IllegalStateException("Could not create configuration directory: " + configDir.getAbsolutePath());
        }
    } catch (SecurityException e) {
        throw new IllegalStateException("Permission denied while creating configuration directory", e);
    }
}

