    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    int start = 0;
    if (!path.isEmpty() && path.charAt(0) == '/') {
        start = 1;
    }
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    int len = path.length();
    for (int i = start; i <= len; i++) {
        if (i == len || path.charAt(i) == '/') {
            String seg = path.substring(start, i);
            String toAdd;
            if (decode) {
                try {
                    toAdd = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
                } catch (java.io.UnsupportedEncodingException e) {
                    throw new java.lang.AssertionError(e);
                }
            } else {
                toAdd = seg;
            }
            segments.add(new PathSegmentImpl(toAdd));
            start = i + 1;
        }
    }
    return segments;
}

